using System.ComponentModel.Composition;
using XrmToolBox.Extensibility;
using XrmToolBox.Extensibility.Interfaces;

namespace PluginFailureCorrelationExplorer
{
    /// <summary>
    /// XrmToolBox entry point (discovered through MEF).
    /// Icons: Resources/icon32.png (SmallImageBase64) and Resources/icon80.png (BigImageBase64).
    /// </summary>
    [Export(typeof(IXrmToolBoxPlugin)),
     ExportMetadata("Name", "Plugin Failure Correlation Explorer"),
     ExportMetadata("Description", "Correlate Dataverse plugin failures, identify recurring exceptions, analyze execution patterns, and generate actionable diagnostic reports."),
     ExportMetadata("SmallImageBase64", ""),
     ExportMetadata("BigImageBase64", ""),
     ExportMetadata("BackgroundColor", "#E6F4F2"),
     ExportMetadata("PrimaryFontColor", "#0B5A54"),
     ExportMetadata("SecondaryFontColor", "#5B6662")]
    public class PluginFailureCorrelationPlugin : PluginBase
    {
        public override IXrmToolBoxPluginControl GetControl()
        {
            return new PluginFailureCorrelationControl();
        }
    }
}
